from __future__ import annotations

import polars as pl
import pytest
from polars.testing import assert_frame_equal

from pipeline import (
    bench_transforms,
    eager_transform,
    lazy_transform,
    make_trips,
    write_plan,
)


@pytest.fixture(scope="module")
def trips() -> pl.DataFrame:
    return make_trips()


def test_schema_and_rows(trips: pl.DataFrame) -> None:
    assert len(trips) == 50_000
    assert set(trips["payment"].unique().to_list()) <= {"card", "cash"}
    assert (trips["pickup_hour"] >= 0).all() and (trips["pickup_hour"] <= 23).all()


def test_lazy_equals_eager(trips: pl.DataFrame) -> None:
    eager = eager_transform(trips)
    lazy = lazy_transform(trips)
    assert_frame_equal(lazy, eager)  # exact: schema, values, order


def test_lazy_collects_exactly_once(
    trips: pl.DataFrame, monkeypatch: pytest.MonkeyPatch
) -> None:
    calls = {"n": 0}
    original = pl.LazyFrame.collect

    def counting_collect(self: pl.LazyFrame, *args, **kwargs):
        calls["n"] += 1
        return original(self, *args, **kwargs)

    monkeypatch.setattr(pl.LazyFrame, "collect", counting_collect)
    result = lazy_transform(trips)
    assert calls["n"] == 1
    assert isinstance(result, pl.DataFrame)


def test_plan_written(tmp_path, trips: pl.DataFrame) -> None:
    plan_path = tmp_path / "plan.txt"
    write_plan(trips, plan_path)
    text = plan_path.read_text()
    assert "SORT" in text.upper() and "AGGREGATE" in text.upper()


def test_benchmark_recorded(tmp_path, trips: pl.DataFrame) -> None:
    bench_path = tmp_path / "bench.txt"
    timings = bench_transforms(trips, repeats=3, path=bench_path)
    lines = bench_path.read_text().splitlines()
    assert any(line.startswith("eager") for line in lines)
    assert any(line.startswith("lazy") for line in lines)
    # no speed assertion — just record positive timings
    assert timings["eager"] > 0 and timings["lazy"] > 0
